#include <array>
#include <cstddef>
#include <omp.h>
#include <vector>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    // Reset output
    bins = {0u, 0u, 0u, 0u};

    // Per-thread local bins to avoid races
    const int maxThreads = omp_get_max_threads();
    std::vector<std::array<size_t, 4>> local(static_cast<std::size_t>(maxThreads),
                                             std::array<size_t, 4>{0u, 0u, 0u, 0u});

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &b = local[static_cast<std::size_t>(tid)];

#pragma omp for
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Bin rule matching example:
            // Q0: x > 0, y > 0
            // Q1: x <= 0, y > 0
            // Q2: x <= 0, y <= 0
            // Q3: x > 0, y <= 0
            std::size_t q;
            if (y > 0) {
                q = (x > 0) ? 0u : 1u;
            } else {
                q = (x > 0) ? 3u : 2u;
            }
            ++b[q];
        }
    }

    // Combine per-thread bins (single-threaded, race-free)
    for (const auto &b : local) {
        bins[0] += b[0];
        bins[1] += b[1];
        bins[2] += b[2];
        bins[3] += b[3];
    }
}
